    "factor_updates": [
      {
        "factor": "Leading CDU/Greens top-two dynamic in polls",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Contemporary polls consistently show CDU/Greens ahead of AfD, suppressing the probability of AfD winning the most seats."
      },
      {
        "factor": "AfD polling share in the high-teens to low-20s",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "AfD's 18–21% support trails CDU/Greens and is unlikely to translate into a plurality of seats."
      },
      {
        "factor": "Occasional poll readings showing AfD ahead of Greens",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Some readings show AfD ahead of Greens, implying limited upside but not robust enough to overturn the top-two dynamic."
      },
      {
        "factor": "Historical base-rate: AfD has never won the most seats in BW",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "A long-standing pattern reduces the a priori probability of AfD achieving a BW top-seat."
      },
      {
        "factor": "Electoral-system constraints (5% threshold, 120 seats, MMP)",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "The rule-set and seat allocation make a single-party majority unlikely for AfD even with sizable support."
      },
      {
        "factor": "Coalition dynamics and governance incentives after the election",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Even with robust vote shares, post-election coalitions are likely to marginalize AfD's chance to hold the most seats."
      }
    ],
    "synthesis_rationale": "All credible factors point toward a negligible probability; but to avoid overconfidence, a minimal posterior above zero is retained (0.01) to reflect occasional upside risk in outlier polls. Correlated factors were treated conservatively in aggregation, and the anchor plus base rates heavily pull the synthesis toward near-zero."
  }
